return items.map((item, index) => {
  return {
    json: {
      number: index + 1,
      url: item.json.url,
      numberedUrl: `${index + 1}. ${item.json.url}`
    }
  };
});

const item = items[0];

// Compose combined content in the desired order
const combinedContent = [
  item.json.Titlte || '',
  item.json.Introduction || '',
  item.json.TOC || '',
  item.json.Content || '',
  item.json.Sources || ''
].join('\n\n');

// 1. Plain HTML version
item.json.CombinedHTML = combinedContent;

// 2. JSON-safe version: Escapes all backslashes, double quotes, and line breaks
item.json.CombinedHTML_JSON = combinedContent
  .replace(/\\/g, '\\\\')     // Escape any backslashes first!
  .replace(/"/g, '\\"')       // Escape double quotes
  .replace(/\n/g, '\\n');     // Escape line breaks

return items;

